/// <summary>
/// This class is the service for the Picklist registration pending process.
/// </summary>
class METDallasPicklistRegPendingProcessService extends SysOperationServiceBase
{
}

Method.Source:
/// <summary>
/// Schedules tasks for the MET Dallas picklist registration pending process.   
/// </summary>
/// <param name = "_contract">
/// <c>METDallasPicklistRegPendingProcessContract</c>.
/// </param>
public void processOperation(METDallasPicklistRegPendingProcessContract _contract)
{
    #OCCRetryCount

    METDallasPicklistRegPendingProcess            pendingProcess;
    METDallasPicklistRegPendingProcessContract    metDataContract;
    SysOperationServiceController                 controller;
    WMSRouteId                                    lastRouteId;
    Int                                           bundlesize;
    container                                     conPicklistPendingRecIds, conOrderTransRoute;
    BatchHeader                                   batchHeader;
    int                                           counter = 0;
    int                                           totalTasks = _contract.parmParallelTasksNumber();
    Query                                         query = _contract.getQuery();

    QueryBuildDataSource qbds = query.dataSourceTable(tableNum(METDallasPicklistRegPendingProcess));
    qbds.sortClear();
    qbds.addSortField(fieldNum(METDallasPicklistRegPendingProcess, routeId), SortOrder::Ascending);

    if (totalTasks  <= 0)
    {
        totalTasks  = 1;
    }

    batchHeader = this.getCurrentBatchHeader();

    if (batchHeader == null)
    {
        batchHeader = batchHeader::construct();
    }

    try
    {
        QueryRun queryRun = new QueryRun(query);

        Map routeIdMap = new Map(Types::String, Types::Container);

        while (queryRun.next())
        {
            pendingProcess = queryRun.get(tableNum(METDallasPicklistRegPendingProcess));

            if (!routeIdMap.exists(pendingProcess.routeId))
            {
                conOrderTransRoute = conNull();
                conOrderTransRoute += pendingProcess.RecId;
            }
            else
            {
                conOrderTransRoute = routeIdMap.lookup(pendingProcess.routeId);
                conOrderTransRoute += pendingProcess.RecId;
            }

            routeIdMap.insert(pendingProcess.routeId, conOrderTransRoute);
        }

        bundleSize = real2int(roundUp((routeIdMap.elements() / totalTasks), 1.0));
        var mapEnumerator = routeIdMap.getEnumerator();

        while (mapEnumerator && mapEnumerator.moveNext())
        {
            conOrderTransRoute = mapEnumerator.currentValue();

            counter += 1;

            if (counter == 1)
            {
                conPicklistPendingRecIds = conNull();
            }

            conPicklistPendingRecIds += conOrderTransRoute;

            if (counter >= bundlesize) 
            {
                controller  = new SysOperationServiceController(
                                            classStr(METPickingListRegistrationPostingJob),
                                            methodStr(METPickingListRegistrationPostingJob, shortPickDeliveryReminderUpdInBundle));

                controller.parmDialogCaption(strFmt("@MET:DallasPicklistRegPendingProcessSubTask", counter));

                metDataContract = controller.getDataContractObject() as METDallasPicklistRegPendingProcessContract;
                metDataContract.conPicklistPendingRecords(conPicklistPendingRecIds);

                batchHeader.addRuntimeTask(controller, this.getCurrentBatchTask().RecId);

                counter = 0;
            }
        }

        if (counter > 0)
        {
            controller  = new SysOperationServiceController(
                                            classStr(METPickingListRegistrationPostingJob),
                                            methodStr(METPickingListRegistrationPostingJob, shortPickDeliveryReminderUpdInBundle));

            controller.parmDialogCaption(strFmt("@MET:DallasPicklistRegPendingProcessSubTask", counter));

            metDataContract = controller.getDataContractObject() as METDallasPicklistRegPendingProcessContract;
            metDataContract.conPicklistPendingRecords(conPicklistPendingRecIds);

            batchHeader.addRuntimeTask(controller, this.getCurrentBatchTask().RecId);
        }

        batchHeader.save();
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
}
